{
  "items": [
    {
      "path": "tools.opencode.session_move",
      "description": "Move a session to another directory, or omit sessionID to move the current session. The current session moves at the next safe boundary; do not run destination-dependent tools in the same execute call.",
      "signature": "tools.opencode.session_move({
  /** Omit to move the current session. @pattern ^ses */
  sessionID?: string,
  /** Destination directory, relative to the target session's directory or absolute. Supports ~. @minLength 1 */
  directory: string,
}): Promise<{
  /** @pattern ^ses */
  sessionID: string,
  directory: string,
}>"
    },
    {
      "path": "tools.elevenlabs.make_outbound_call",
      "description": "Make an outbound call using an ElevenLabs agent. Automatically detects provider type (Twilio or SIP trunk) and uses the appropriate API.

    ⚠️ COST WARNING: This tool makes an API call to ElevenLabs which may incur costs. Only use when explicitly requested by the user.

    Args:
        agent_id: The ID of the agent that will handle the call
        agent_phone_number_id: The ID of the phone number to use for the call
        to_number: The phone number to call (E.164 format: +1xxxxxxxxxx)

    Returns:
        TextContent containing information about the call
    ",
      "signature": "tools.elevenlabs.make_outbound_call({
  agent_id: string,
  agent_phone_number_id: string,
  to_number: string,
}): Promise<{
  type: "text",
  text: string,
  /** @default null */
  annotations?: {
      /** @default null */
      audience?: Array<"user" | "assistant"> | null,
      /** @default null */
      priority?: number | null,
    } | null,
  /** @default null */
  _meta?: {} | null,
}>"
    },
    {
      "path": "tools.elevenlabs.simulate_conversation",
      "description": "Simulate a text conversation between a conversational AI agent and a
    simulated user. Runs the full conversation and returns the transcript plus analysis.

    Use this to test agent behaviour, evaluate prompts, and catch failure modes without
    a live call. The simulated user follows the persona you describe.

    ⚠️ COST WARNING: This tool makes an API call to ElevenLabs which may incur costs.
    Only use when explicitly requested by the user.

    Args:
        agent_id: ID of the agent to test. Use list_agents to find IDs.
        simulated_user_prompt: Instructions for how the simulated user should behave.
            Example: "You are a frustrated customer who cannot find the cancel button."
        first_message: Optional opening message to kick off the conversation.
        extra_evaluation_criteria: Optional list of dicts, each with:
            - id (str): unique key e.g. "issue_resolved"
            - name (str): human label e.g. "Issue Resolved"
            - conversation_goal_prompt (str): the assertion to check
              e.g. "The agent fully resolved the user's issue."
            - use_knowledge_base (bool, optional): whether the evaluator should
              reference the agent's knowledge base when judging. Defaults to False.
        max_turns: Maximum conversation turns. Defaults to 10.
    ",
      "signature": "tools.elevenlabs.simulate_conversation({
  agent_id: string,
  simulated_user_prompt: string,
  /** @default null */
  first_message?: string | null,
  /** @default null */
  extra_evaluation_criteria?: Array<{}> | null,
  /** @default 10 @integer */
  max_turns?: number,
}): Promise<{
  type: "text",
  text: string,
  /** @default null */
  annotations?: {
      /** @default null */
      audience?: Array<"user" | "assistant"> | null,
      /** @default null */
      priority?: number | null,
    } | null,
  /** @default null */
  _meta?: {} | null,
}>"
    },
    {
      "path": "tools.opencode.read_mcp_resource",
      "description": "Read one MCP resource by server and URI. Not for local files. Always return the full contents rather than slicing or filtering them; oversized output is truncated automatically and the full content is saved to a file you can read. Images and PDFs are shown to you directly.",
      "signature": "tools.opencode.read_mcp_resource({
  /** The server field of the discovered resource. */
  server: string,
  /** Exact resource URI from discovery, an expanded uriTemplate, or the user. */
  uri: string,
}): Promise<{
  server: string,
  uri: string,
  contents: Array<{
        type: "text",
        uri: string,
        text: string,
        mimeType?: string,
      } | {
        type: "blob",
        uri: string,
        blob: string,
        mimeType?: string,
      }>,
}>"
    }
  ],
  "remaining": 0,
  "next": null
}

